import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';

class Order extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    this.state = {
      orders: [],
      orderSelected: null
    };
  }

  componentDidMount() {
    this.apiGetOrders();
  }

  // Lấy danh sách đơn hàng từ Server
  apiGetOrders = () => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.get('/api/admin/orders', config).then((res) => {
      this.setState({ orders: res.data });
    });
  };

  // Cập nhật trạng thái đơn hàng (APPROVED, COMPLETED, CANCELED)
  btnUpdateStatusClick = (id, newStatus) => {
    const config = { headers: { 'x-access-token': this.context.token } };
    axios.put(`/api/admin/orders/status/${id}`, { status: newStatus }, config).then((res) => {
      if (res.data) {
        alert(`Đã cập nhật trạng thái đơn hàng thành: ${newStatus}`);
        this.apiGetOrders();
        if (this.state.orderSelected && this.state.orderSelected._id === id) {
          this.setState({ orderSelected: { ...this.state.orderSelected, status: newStatus } });
        }
      }
    });
  };

  // Trả về badge màu sắc tương ứng trạng thái
  renderStatusBadge = (status) => {
    let bgColor = '#FFA000'; // PENDING - Cam
    let label = 'Chờ duyệt';

    if (status === 'APPROVED') {
      bgColor = '#1E88E5'; // APPROVED - Xanh dương
      label = 'Đã duyệt món';
    } else if (status === 'COMPLETED') {
      bgColor = '#2E7D32'; // COMPLETED - Xanh lá
      label = 'Hoàn thành';
    } else if (status === 'CANCELED') {
      bgColor = '#D32F2F'; // CANCELED - Đỏ
      label = 'Đã hủy';
    }

    return (
      <span style={{ padding: '4px 10px', borderRadius: '12px', fontSize: '12px', color: '#FFF', backgroundColor: bgColor, fontWeight: 'bold' }}>
        {label}
      </span>
    );
  };

  render() {
    const { orders, orderSelected } = this.state;

    return (
      <div style={{ padding: '20px' }}>
        <h3 style={{ color: '#4A2E2B', marginBottom: '20px' }}>QUẢN LÝ ĐƠN HÀNG TẠI BÀN</h3>

        {/* Bảng danh sách đơn hàng */}
        <div style={{ backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)', marginBottom: '20px' }}>
          <h4 style={{ marginBottom: '15px' }}>Danh sách đơn hàng mới nhất</h4>
          <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
            <thead>
              <tr style={{ backgroundColor: '#F4EBE1', borderBottom: '2px solid #DDD' }}>
                <th style={{ padding: '10px' }}>Số Bàn</th>
                <th style={{ padding: '10px' }}>Khách hàng</th>
                <th style={{ padding: '10px' }}>Thời gian</th>
                <th style={{ padding: '10px' }}>Tổng tiền</th>
                <th style={{ padding: '10px' }}>Trạng thái</th>
                <th style={{ padding: '10px' }}>Thao tác</th>
              </tr>
            </thead>
            <tbody>
              {orders.map((item) => (
                <tr 
                  key={item._id} 
                  style={{ borderBottom: '1px solid #EEE', cursor: 'pointer', backgroundColor: orderSelected && orderSelected._id === item._id ? '#FFF8E1' : 'transparent' }}
                  onClick={() => this.setState({ orderSelected: item })}
                >
                  <td style={{ padding: '10px', fontWeight: 'bold', color: '#4A2E2B' }}>{item.tableNo || 'Bàn ?'}</td>
                  <td style={{ padding: '10px' }}>
                    <div><b>{item.customerName || 'Khách vãng lai'}</b></div>
                    <div style={{ fontSize: '12px', color: '#666' }}>{item.customerPhone}</div>
                  </td>
                  <td style={{ padding: '10px', fontSize: '13px' }}>
                    {new Date(item.cdate).toLocaleString('vi-VN')}
                  </td>
                  <td style={{ padding: '10px', color: '#C85A32', fontWeight: 'bold' }}>
                    {item.total ? item.total.toLocaleString('vi-VN') + ' đ' : '0 đ'}
                  </td>
                  <td style={{ padding: '10px' }}>{this.renderStatusBadge(item.status)}</td>
                  <td style={{ padding: '10px' }}>
                    {item.status === 'PENDING' && (
                      <>
                        <button
                          onClick={(e) => { e.stopPropagation(); this.btnUpdateStatusClick(item._id, 'APPROVED'); }}
                          style={{ marginRight: '6px', backgroundColor: '#1E88E5', color: '#FFF', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' }}
                        >
                          Duyệt món
                        </button>
                        <button
                          onClick={(e) => { e.stopPropagation(); this.btnUpdateStatusClick(item._id, 'CANCELED'); }}
                          style={{ backgroundColor: '#D32F2F', color: '#FFF', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' }}
                        >
                          Hủy
                        </button>
                      </>
                    )}
                    {item.status === 'APPROVED' && (
                      <button
                        onClick={(e) => { e.stopPropagation(); this.btnUpdateStatusClick(item._id, 'COMPLETED'); }}
                        style={{ backgroundColor: '#2E7D32', color: '#FFF', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' }}
                      >
                        Thanh toán xong
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Chi tiết đơn hàng khi click chọn 1 đơn */}
        {orderSelected && (
          <div style={{ backgroundColor: '#FFF', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.05)' }}>
            <h4 style={{ marginBottom: '15px', color: '#4A2E2B' }}>
              CHI TIẾT ĐƠN HÀNG - {orderSelected.tableNo} ({new Date(orderSelected.cdate).toLocaleTimeString('vi-VN')})
            </h4>
            <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
              <thead>
                <tr style={{ backgroundColor: '#F4EBE1' }}>
                  <th style={{ padding: '10px' }}>Món ăn</th>
                  <th style={{ padding: '10px' }}>Đơn giá</th>
                  <th style={{ padding: '10px' }}>Số lượng</th>
                  <th style={{ padding: '10px' }}>Thành tiền</th>
                </tr>
              </thead>
              <tbody>
                {orderSelected.items && orderSelected.items.map((subItem, index) => (
                  <tr key={index} style={{ borderBottom: '1px solid #EEE' }}>
                    <td style={{ padding: '10px', fontWeight: 'bold' }}>
                      {subItem.product ? subItem.product.name : 'Món ăn'}
                    </td>
                    <td style={{ padding: '10px' }}>
                      {subItem.price ? subItem.price.toLocaleString('vi-VN') + ' đ' : '0 đ'}
                    </td>
                    <td style={{ padding: '10px' }}>{subItem.quantity}</td>
                    <td style={{ padding: '10px', color: '#C85A32', fontWeight: 'bold' }}>
                      {((subItem.price || 0) * subItem.quantity).toLocaleString('vi-VN')} đ
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    );
  }
}

export default Order;
